  def icon(name, class: "size-5", solid: false, **attrs)
    path = solid ? SOLID.fetch(name) : OUTLINE.fetch(name)
    svg_attrs = {xmlns: "http://www.w3.org/2000/svg", viewBox: "0 0 24 24", class: binding.local_variable_get(:class), "aria-hidden": true}.merge(attrs)
    if solid
      content_tag(:svg, tag.path(d: path), svg_attrs.merge(fill: "currentColor"))
    else
      content_tag(:svg, tag.path(d: path, "stroke-linecap": "round", "stroke-linejoin": "round"),
        svg_attrs.merge(fill: "none", stroke: "currentColor", "stroke-width": "1.75"))
    end
  end
